document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("project-pricing-form");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("baseProjectCost").value),r=parseFloat(document.getElementById("baseProjectHours").value),t=parseInt(document.getElementById("baseProjectComplexity").value),i=parseInt(document.getElementById("currentComplexity").value),o=document.getElementById("timelinePressure").value,d=document.getElementById("clientTier").value,a=document.getElementById("projectScope").value,s=document.getElementById("riskLevel").value,c=parseInt(document.getElementById("revisions").value),l=parseFloat(document.getElementById("profitMargin").value)/100,g=n/r,u=i/t,m={relaxed:.9,normal:1,tight:1.3,rush:1.8},p={startup:.8,medium:1,enterprise:1.4,nonprofit:.7},v={smaller:.5,similar:1,larger:1.5,"much-larger":2},b={low:1.1,medium:1.2,high:1.4};let h=n*u*m[o]*p[d]*v[a]*b[s];const f=.1*h*c;h+=f;const $=h*(1+l),y=r*u*v[a]*("rush"===o?1.2:1),M=$/y,x=h,S=$,E=1.3*$,B=.4*$,I=.4*$,k=.2*$;let L="";L="high"===s||"rush"===o?"⚠️ High-risk project - consider additional scope protection":i>t+1?"📈 Significant complexity increase - monitor scope carefully":"✅ Manageable risk level with proper planning";document.getElementById("project-pricing-result").innerHTML=`\n      <h3>💼 Project Pricing Analysis</h3>\n      \n      <div class="insight-cards">\n        <div class="insight-card warning">\n          <h6>💰 Cost-Based Price</h6>\n          <div class="big-number">$${Math.round(x).toLocaleString()}</div>\n          <p>Covers costs + risk buffer<br>\n          No profit margin<br>\n          Minimum viable price</p>\n        </div>\n        \n        <div class="insight-card success">\n          <h6>🎯 Recommended Price</h6>\n          <div class="big-number">$${Math.round(S).toLocaleString()}</div>\n          <p>Includes ${100*l}% profit margin<br>\n          $${Math.round(M)} effective hourly<br>\n          Sustainable pricing</p>\n        </div>\n        \n        <div class="insight-card info">\n          <h6>🚀 Premium Price</h6>\n          <div class="big-number">$${Math.round(E).toLocaleString()}</div>\n          <p>High-value positioning<br>\n          Expert-level pricing<br>\n          Test market response</p>\n        </div>\n      </div>\n\n      <div style="margin-top: 2rem; padding: 1.5rem; background: #f8f9fa; border-radius: 12px;">\n        <h4>📊 Project Analysis Breakdown</h4>\n        \n        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-top: 1rem;">\n          <div>\n            <strong>📈 Pricing Adjustments:</strong><br>\n            Base project: $${n.toLocaleString()}<br>\n            Complexity: ${(100*u).toFixed(0)}% (${i} vs ${t})<br>\n            Timeline: ${(100*m[o]).toFixed(0)}% (${o})<br>\n            Client tier: ${(100*p[d]).toFixed(0)}% (${d})<br>\n            Scope: ${(100*v[a]).toFixed(0)}% (${a})<br>\n            Risk buffer: ${(100*b[s]).toFixed(0)}% (${s} risk)\n          </div>\n          \n          <div>\n            <strong>⏱️ Time Estimation:</strong><br>\n            Base project hours: ${r}<br>\n            Estimated hours: ${Math.round(y)}<br>\n            Base hourly rate: $${Math.round(g)}<br>\n            Effective hourly: $${Math.round(M)}<br>\n            Revisions included: ${c} rounds<br>\n            Revision cost: $${Math.round(f).toLocaleString()}\n          </div>\n        </div>\n        \n        <div style="margin-top: 1.5rem; padding: 1rem; background: white; border-radius: 8px;">\n          <strong>💳 Suggested Payment Schedule (${100*l}% margin):</strong><br>\n          <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1rem; margin-top: 0.5rem; text-align: center;">\n            <div style="padding: 0.5rem; background: #e8f5e8; border-radius: 6px;">\n              <strong>40% Upfront</strong><br>\n              $${Math.round(B).toLocaleString()}\n            </div>\n            <div style="padding: 0.5rem; background: #e3f2fd; border-radius: 6px;">\n              <strong>40% Milestone</strong><br>\n              $${Math.round(I).toLocaleString()}\n            </div>\n            <div style="padding: 0.5rem; background: #fff3cd; border-radius: 6px;">\n              <strong>20% Completion</strong><br>\n              $${Math.round(k).toLocaleString()}\n            </div>\n          </div>\n        </div>\n        \n        <div style="margin-top: 1rem; padding: 1rem; background: ${"high"===s?"#f8d7da":"medium"===s?"#fff3cd":"#d4edda"}; border-radius: 8px; border-left: 4px solid ${"high"===s?"#dc3545":"medium"===s?"#ffc107":"#28a745"};">\n          <strong>🎯 Pricing Strategy:</strong><br>\n          ${L}<br><br>\n          \n          <strong>💡 Negotiation Tips:</strong><br>\n          • Start with recommended price ($${Math.round(S).toLocaleString()}) for value-focused clients<br>\n          • Minimum acceptable: $${Math.round(x).toLocaleString()}} (covers costs but no profit)<br>\n          • Premium positioning: $${Math.round(E).toLocaleString()}} for enterprise clients<br>\n          • Include scope change process and hourly rate for additional work<br>\n          • Consider offering package options at different service levels\n        </div>\n      </div>\n    `})});